interface FieldMonitorMapProps {
    parcel: Parcel;
}

const FieldMonitorMap: React.FC<FieldMonitorMapProps> = ({ parcel }) => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstanceRef = useRef<any>(null);
    const overlayRef = useRef<any>(null);
    const [activeLayer, setActiveLayer] = useState<'ndvi' | 'ndre' | 'ndmi' | 'lai' | 'lst'>('ndvi');
    const [loadingLayer, setLoadingLayer] = useState(false);

    useEffect(() => {
        if (!mapRef.current || !window.google || mapInstanceRef.current) return;
        mapInstanceRef.current = new window.google.maps.Map(mapRef.current, {
            center: { lat: 56.2639, lng: 9.5018 },
            zoom: 13,
            mapTypeId: 'hybrid',
            disableDefaultUI: true,
            zoomControl: true,
        });
    }, []);

    useEffect(() => {
        if (!mapInstanceRef.current || !parcel.boundary || !window.google) return;
        const polygon = new window.google.maps.Polygon({
            paths: parcel.boundary,
            strokeColor: '#f59e0b',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            fillColor: '#fbbf24',
            fillOpacity: 0.0,
        });
        polygon.setMap(mapInstanceRef.current);
        const bounds = new window.google.maps.LatLngBounds();
        if (Array.isArray(parcel.boundary)) {
            const isMulti = Array.isArray(parcel.boundary[0]);
            if (isMulti) (parcel.boundary as any[]).forEach(ring => ring.forEach((p: any) => bounds.extend(p)));
            else (parcel.boundary as any[]).forEach((p: any) => bounds.extend(p));
        }
        mapInstanceRef.current.fitBounds(bounds);
        return () => polygon.setMap(null);
    }, [parcel]);

    useEffect(() => {
        if (!mapInstanceRef.current || !parcel.boundary) return;
        const loadLayer = async () => {
            setLoadingLayer(true);
            try {
                if (overlayRef.current) mapInstanceRef.current.overlayMapTypes.removeAt(0);
                const backendUrl = getBackendUrl();
                const result = await fetchGeeLayer(activeLayer, parcel.boundary, backendUrl);
                const tileUrl = result?.tile_url;
                if (tileUrl) {
                    const mapType = new window.google.maps.ImageMapType({
                        getTileUrl: (coord: any, zoom: any) => tileUrl.replace('{x}', coord.x).replace('{y}', coord.y).replace('{z}', zoom),
                        tileSize: new window.google.maps.Size(256, 256),
                        opacity: 0.85,
                    });
                    mapInstanceRef.current.overlayMapTypes.push(mapType);
                    overlayRef.current = mapType;
                }
            } catch (e) { console.error(e); } finally { setLoadingLayer(false); }
        };
        loadLayer();
    }, [activeLayer, parcel]);

    return (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
            <div className="p-3 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-700 flex items-center gap-2 text-sm"><Layers size={14} /> Satellite Imagery</h3>
                <div className="flex bg-white border border-gray-200 rounded-lg p-0.5">
                    {['ndvi', 'ndre', 'ndmi'].map(lid => (
                        <button key={lid} onClick={() => setActiveLayer(lid as any)} className={`px-2 py-1 text-[10px] font-bold rounded-md transition-all ${activeLayer === lid ? 'bg-emerald-100 text-emerald-800' : 'text-gray-500 hover:bg-gray-50'}`}>{lid.toUpperCase()}</button>
                    ))}
                </div>
            </div>
            <div className="relative h-[300px] w-full bg-gray-100">
                <div ref={mapRef} className="absolute inset-0 w-full h-full" />
                {loadingLayer && (
                    <div className="absolute top-4 right-4 bg-white/90 px-3 py-1.5 rounded-lg shadow-sm text-[10px] font-bold flex items-center gap-2 z-10">
                        <RefreshCw className="animate-spin text-emerald-600" size={12} /> ANALYZING...
                    </div>
                )}
            </div>
        </div>
    );
};

export const FieldDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { parcels, updateParcel } = useParcels();
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [soil, setSoil] = useState<SoilData | null>(null);
  const [loadingSoil, setLoadingSoil] = useState(true);
  const [loading, setLoading] = useState(true);
  const [ndviHistory, setNdviHistory] = useState<NdviPoint[]>([]);
  const [loadingStats, setLoadingStats] = useState(false);

  const parcel = parcels.find(p => p.id === id);

  const fetchStats = async (currentParcel: Parcel) => {
      if (!currentParcel.boundary) return;
      setLoadingStats(true);
      try {
          const backendUrl = getBackendUrl();
          const startDate = currentParcel.date || new Date().toISOString().split('T')[0];
          const endDate = new Date().toISOString().split('T')[0];
          const realData = await fetchGeeTimeSeries(currentParcel.boundary, startDate, endDate, backendUrl);
          if (realData && realData.length > 0) {
              setNdviHistory(realData);
              updateParcel(currentParcel.id, { ndviHistory: realData, lastAgroSync: Date.now() });
          } else if (currentParcel.ndviHistory) {
              setNdviHistory(currentParcel.ndviHistory);
          }
      } catch (e) {
          if (currentParcel.ndviHistory) setNdviHistory(currentParcel.ndviHistory);
      } finally { setLoadingStats(false); }
  };

  useEffect(() => {
    if (!parcel) return;
    const { lat, lng } = getCoordinates(parcel.location);
    fetchFieldWeather(lat, lng).then(data => { setWeather(data); setLoading(false); });
    setLoadingSoil(true);
    fetchSoilData(lat, lng).then(data => setSoil(data)).finally(() => setLoadingSoil(false));
    if (parcel.ndviHistory && parcel.ndviHistory.length > 0) {
        setNdviHistory(parcel.ndviHistory);
        const oneDay = 24 * 60 * 60 * 1000;
        if (!parcel.lastAgroSync || Date.now() - parcel.lastAgroSync > oneDay) fetchStats(parcel);
    } else { fetchStats(parcel); }
  }, [parcel?.id]);

  if (!parcel) return <div className="p-8 text-center">Field not found.</div>;

  const formatDate = (d: string) => d ? new Date(d).toLocaleDateString('en-DK', { weekday: 'short', day: 'numeric' }) : 'N/A';

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex items-center gap-4">
        <button onClick={() => navigate('/dashboard')} className="p-2 bg-white border border-gray-200 rounded-lg text-gray-400 hover:text-gray-600"><ArrowLeft size={20}/></button>
        <div>
          <h1 className="text-2xl font-bold text-gray-900">{parcel.name}</h1>
          <p className="text-xs text-gray-500 flex items-center gap-1 mt-0.5"><MapPin size={12}/> {parcel.location}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="space-y-6">
          <FieldMonitorMap parcel={parcel} />
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h3 className="text-sm font-bold text-gray-900 mb-4 uppercase tracking-wider">Crop Profile</h3>
            <div className="space-y-3">
              <div className="flex justify-between text-sm"><span className="text-gray-500">Type</span><span className="font-bold">{parcel.crop}</span></div>
              <div className="flex justify-between text-sm"><span className="text-gray-500">Hectares</span><span className="font-bold">{parcel.size} ha</span></div>
              <div className="flex justify-between text-sm"><span className="text-gray-500">Latest NDVI</span><span className="font-bold">{ndviHistory.length > 0 ? ndviHistory[ndviHistory.length-1].value?.toFixed(2) : 'N/A'}</span></div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h3 className="text-sm font-bold text-gray-900 mb-6 uppercase tracking-wider flex items-center gap-2"><Activity size={16} className="text-emerald-600"/> Vegetation Health Trend</h3>
            <div className="h-64">
              {loadingStats && ndviHistory.length === 0 ? (
                <div className="h-full flex items-center justify-center text-gray-400 text-xs italic">Processing satellite data...</div>
              ) : ndviHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={ndviHistory}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                    <XAxis dataKey="date" tickFormatter={(v) => new Date(v).toLocaleDateString(undefined, {month:'short', day:'numeric'})} tick={{fontSize: 10}} axisLine={false} tickLine={false} />
                    <YAxis domain={[0,1]} tick={{fontSize: 10}} axisLine={false} tickLine={false} />
                    <Tooltip />
                    <Line type="monotone" dataKey="value" stroke="#10b981" strokeWidth={3} dot={{r: 3, fill:'#10b981'}} />
                  </LineChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-gray-50 rounded-lg border-2 border-dashed border-gray-100">
                  <Ban size={24} className="mb-2 opacity-20" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Analysis Data Available</p>
                  <p className="text-[10px] mt-1">Satellite data for this field is pending generation.</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h3 className="text-sm font-bold text-gray-900 mb-4 uppercase tracking-wider">Environmental Summary</h3>
            {loading ? <div className="h-20 animate-pulse bg-gray-50 rounded-lg"></div> : weather && (
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <div className="bg-gray-50 p-4 rounded-xl text-center">
                  <span className="text-[10px] font-bold text-gray-400 uppercase">Temp</span>
                  <div className="text-xl font-bold">{weather.current.temperature}°</div>
                </div>
                <div className="bg-gray-50 p-4 rounded-xl text-center">
                  <span className="text-[10px] font-bold text-gray-400 uppercase">Wind</span>
                  <div className="text-xl font-bold">{weather.current.windSpeed} <span className="text-[10px] font-normal">km/h</span></div>
                </div>
                <div className="bg-gray-50 p-4 rounded-xl text-center">
                  <span className="text-[10px] font-bold text-gray-400 uppercase">Precip</span>
                  <div className="text-xl font-bold">{weather.daily[0].rainSum} <span className="text-[10px] font-normal">mm</span></div>
                </div>
                <div className="bg-gray-50 p-4 rounded-xl text-center">
                  <span className="text-[10px] font-bold text-gray-400 uppercase">Humidity</span>
                  <div className="text-xl font-bold">{weather.current.humidity}%</div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
